logic:
/*
Name: frmOARamoTecnico
Author: Global
Description: Objeto afectado del reclamo para el ramo 96 (ramos tecnicos). Muestra en dos pestanas los datos
             del objeto asegurado DT_RAMO_TECNICO de la poliza; solo son editables la descripcion, la
             localizacion, el proyecto y la descripcion del evento. Sin comandos ni triggers: toda la logica
             vive en el formulario.
Category: FORM
Version: 1.00
CreateDate: 30-09-2026
*/

var me = this;

(function () {
  var policyId = Number(context && context.policyId);
  var lob = String(context && context.lob || '96');
  var OBJECT_CODE = 'DT_RAMO_TECNICO';
  var OBJECT_FORM_ID = 663;

  var TAB1 = ['txtActividadEconomica', 'txtDescripcion', 'txtLocalizacion', 'txtProyecto', 'txtDescripcionEvento'];
  var TAB2 = ['txtCategoria', 'txtMarca', 'txtModelo', 'txAnio', 'txtSerie', 'txtTipo', 'txtPropietario', 'txtCantidad'];
  // Solo lectura: se recuperan siempre del objeto asegurado de la poliza.
  var READ_ONLY = ['txtActividadEconomica', 'txtCategoria', 'txtMarca', 'txtModelo', 'txAnio', 'txtSerie', 'txtTipo',
    'txtPropietario', 'txtCantidad'];
  // Editables: se precargan del objeto asegurado solo en un objeto afectado nuevo y vacio.
  var PREFILL = { txtDescripcion: 'txtDescripcion', txtLocalizacion: 'txtLocalizacion', txtProyecto: 'txtProyecto' };
  var PLAIN = { txAnio: 'txAnio', txtSerie: 'txtSerie', txtTipo: 'txtTipo', txtPropietario: 'txtPropietario', txtCantidad: 'txtCantidad' };

  var CSS = [
    '.oa-rt-tabs{display:flex;gap:4px;margin:0 0 12px;border-bottom:1px solid #d9e1ec}',
    '.oa-rt-tab{padding:6px 14px;cursor:pointer;color:#60708a;font-size:13px;border:1px solid transparent;',
    'border-bottom:none;border-radius:5px 5px 0 0;margin-bottom:-1px;user-select:none}',
    '.oa-rt-tab.active{color:#183153;font-weight:600;background:#fff;border-color:#d9e1ec}',
    '.oa-rt-hidden{display:none!important}',
    '.oa-rt-readonly{background:#f5f7fa!important;color:#44546a!important;cursor:default}'
  ].join('');

  function rootForm() {
    var $root = $('.rendered-form').first();
    if (!$root.length) $root = $('[name="txtDescripcionEvento"]').closest('form');
    return $root;
  }

  function control($root, name) {
    return $root.find('[name="' + name + '"]');
  }

  function valueOf($root, name) {
    var value = control($root, name).val();
    return value === null || value === undefined ? '' : String(value).trim();
  }

  function fire(element, type) {
    if (typeof Event === 'function') {
      element.dispatchEvent(new Event(type, { bubbles: true }));
    } else {
      $(element).trigger(type);
    }
  }

  // Asigna el valor y avisa a la pantalla para que lo guarde con el objeto afectado.
  function setValue($root, name, value) {
    var $control = control($root, name);
    if (!$control.length) return;
    var text = value === null || value === undefined ? '' : String(value).trim();
    if (String($control.val() || '') === text) return;
    $control.val(text);
    fire($control[0], 'input');
    fire($control[0], 'change');
  }

  function message($root, text, type) {
    $root.find('.oa-rt-status').remove();
    if (!text) return;
    $('<div class="oa-rt-status alert alert-' + type + '"></div>').text(text).prependTo($root);
  }

  function addStyle($root) {
    if ($root.find('style.oa-rt-style').length) return;
    $('<style class="oa-rt-style"></style>').text(CSS).prependTo($root);
  }

  function rowOf($root, name) {
    var $control = control($root, name);
    var $row = $control.closest('.row');
    return $row.length && $root.has($row[0]).length ? $row : $control.closest('.form-group');
  }

  function buildTabs($root) {
    if ($root.find('.oa-rt-tabs').length) return;
    var $tabs = $('<div class="oa-rt-tabs" role="tablist"></div>');
    var $general = $('<div class="oa-rt-tab active" role="tab" tabindex="0" data-tab="1">Datos Generales</div>');
    var $extra = $('<div class="oa-rt-tab" role="tab" tabindex="0" data-tab="2">Datos Adicionales</div>');
    $tabs.append($general).append($extra);
    var $first = rowOf($root, TAB1[0]);
    if ($first.length) $tabs.insertBefore($first); else $tabs.prependTo($root);

    function show(tab) {
      $tabs.find('.oa-rt-tab').each(function () {
        $(this).toggleClass('active', String($(this).attr('data-tab')) === String(tab));
      });
      TAB1.forEach(function (name) { rowOf($root, name).toggleClass('oa-rt-hidden', String(tab) !== '1'); });
      TAB2.forEach(function (name) { rowOf($root, name).toggleClass('oa-rt-hidden', String(tab) !== '2'); });
    }
    $tabs.on('click', '.oa-rt-tab', function () { show($(this).attr('data-tab')); });
    $tabs.on('keydown', '.oa-rt-tab', function (event) {
      if (event.key === 'Enter' || event.key === ' ') { event.preventDefault(); show($(this).attr('data-tab')); }
    });
    show('1');
  }

  function lockReadOnly($root) {
    READ_ONLY.forEach(function (name) {
      control($root, name).prop('readonly', true).attr('aria-readonly', 'true').attr('tabindex', '-1')
        .addClass('oa-rt-readonly');
    });
  }

  function objectValues(insuredObject) {
    var fields = [];
    try { fields = JSON.parse(insuredObject && insuredObject.jValues || '[]'); } catch (error) { fields = []; }
    var values = {};
    (Array.isArray(fields) ? fields : []).forEach(function (field) {
      if (!field || typeof field.name !== 'string' || values[field.name] !== undefined) return;
      var data = Array.isArray(field.userData) ? field.userData : [];
      var first = data.length && data[0] !== null && data[0] !== undefined ? String(data[0]).trim() : '';
      // Valores de relleno del constructor de formularios: no son datos.
      values[field.name] = /^option-\d+$/i.test(first) ? '' : first;
    });
    return values;
  }

  function selectObject(rows) {
    var objects = Array.isArray(rows) ? rows.filter(function (row) { return row && row.jValues; }) : [];
    return objects.find(function (row) {
      return String(row.ObjectDefinition && row.ObjectDefinition.code || '').toUpperCase() === OBJECT_CODE;
    }) || objects.find(function (row) {
      return Number(row.ObjectDefinition && row.ObjectDefinition.formId) === OBJECT_FORM_ID;
    }) || null;
  }

  function loadTable(name) {
    return me.exe('GetFullTable', { table: name }).then(function (result) {
      return Array.isArray(result && result.outData) ? result.outData : [];
    }).catch(function () { return []; });
  }

  function cell(row, index) {
    return Array.isArray(row) && row[index] !== null && row[index] !== undefined ? String(row[index]).trim() : '';
  }

  // Busca el nombre de un codigo en una tabla de catalogo; si no esta, muestra el codigo guardado.
  function labelOf(rows, code, codeIndex, nameIndex, match) {
    if (!code) return '';
    var candidates = rows.filter(function (row) { return cell(row, codeIndex) === code && (!match || match(row)); });
    var name = candidates.length ? cell(candidates[0], nameIndex) : '';
    return name || code;
  }

  function apply($root, values, catalogs, isNew) {
    var activity = values.cmbActividadEconomica || '';
    var category = values.cmbCategoria || '';
    var brand = values.cmbMarca || '';
    var model = values.cmbModelo || '';
    setValue($root, 'hdnActividadEconomica', activity);
    setValue($root, 'hdnCategoria', category);
    setValue($root, 'hdnMarca', brand);
    setValue($root, 'hdnModelo', model);
    setValue($root, 'txtActividadEconomica', labelOf(catalogs.actividad, activity, 0, 1));
    setValue($root, 'txtCategoria', labelOf(catalogs.categoria, category, 0, 1));
    // Las marcas se comparten entre ramos: primero la del ramo de la poliza.
    var ownBrand = catalogs.marcas.some(function (row) { return cell(row, 0) === lob && cell(row, 1) === brand; });
    setValue($root, 'txtMarca', labelOf(catalogs.marcas, brand, 1, 2, ownBrand ? function (row) {
      return cell(row, 0) === lob;
    } : null));
    setValue($root, 'txtModelo', labelOf(catalogs.modelos, model, 2, 3, function (row) {
      return cell(row, 0) === lob && cell(row, 1) === brand;
    }));
    Object.keys(PLAIN).forEach(function (name) { setValue($root, name, values[PLAIN[name]]); });
    if (isNew) {
      Object.keys(PREFILL).forEach(function (name) {
        if (!valueOf($root, name)) setValue($root, name, values[PREFILL[name]]);
      });
    }
  }

  function initialize() {
    var $root = rootForm();
    if (!$root.length) return;
    addStyle($root);
    buildTabs($root);
    lockReadOnly($root);
    if (!Number.isSafeInteger(policyId) || policyId <= 0) {
      message($root, 'No se recibió una póliza válida para cargar el objeto asegurado.', 'warning');
      return;
    }
    var isNew = !valueOf($root, 'hdnInsuredObjectId');
    message($root, 'Cargando datos del objeto asegurado...', 'info');
    var objectRequest = me.exe('RepoInsuredObject', {
      operation: 'GET', filter: 'lifePolicyId=' + policyId, include: ['ObjectDefinition'], size: 100
    });
    Promise.all([objectRequest, loadTable('actividad'), loadTable('tbCategoriaMaquinaria'), loadTable('tbMarcas'),
      loadTable('tbModelos')]).then(function (results) {
      var insuredObject = selectObject(results[0] && results[0].outData);
      if (!insuredObject) {
        message($root, 'La póliza no tiene un objeto asegurado de ramos técnicos (DT_RAMO_TECNICO).', 'warning');
        return;
      }
      apply($root, objectValues(insuredObject), {
        actividad: results[1], categoria: results[2], marcas: results[3], modelos: results[4]
      }, isNew);
      setValue($root, 'hdnInsuredObjectId', insuredObject.id);
      message($root, '', 'info');
    }).catch(function () {
      message($root, 'No fue posible cargar los datos del objeto asegurado.', 'danger');
    });
  }

  initialize();
})();
